-- ============================================================================
-- IMPORTACION DEL LIBRO DE VUELO EN PAPEL (Excel: Libro_de_vuelo_ARG.xlsx)
-- Usuario: fileretocambrafrancisco@gmail.com
-- Aeronaves nuevas: 12  ·  Vuelos: 155  ·  Rango: 06/10/2022 — 22/11/2025
--
-- Pegar y correr en el SQL Editor de Supabase (Dashboard > SQL Editor >
-- New query). Es seguro re-ejecutar: no duplica aeronaves (usa NOT EXISTS
-- por matrícula) pero SÍ duplicaría los vuelos si lo corrés dos veces —
-- correlo una sola vez.
--
-- Decisiones tomadas al convertir el excel (confirmadas con el piloto):
--   - Todos los aterrizajes se cargaron como "de día" (el excel no separaba
--     aterrizajes día/noche en columnas propias, y no hubo vuelos nocturnos
--     en este período).
--   - Finalidad del vuelo, mapeada desde los códigos del excel:
--       INST -> instruccion · EXA -> verificacion · ADAP/ENTT/VP -> adiestramiento
--     (ENTT y VP son la misma actividad —entrenamiento—, solo cambiaba si
--     era en la escuela o en avión privado; esa distinción original queda
--     igual anotada en el campo "observaciones" de cada vuelo.)
--   - Todas las aeronaves se cargaron como clase "monomotor" / medio
--     "terrestre" (no había evidencia de multimotor/reactor/hidro en el
--     excel). Las tarifas por hora quedan en 0 — cargalas desde la app en
--     Aeronaves para que el costo se calcule bien de acá en adelante.
--   - La matrícula "L-S048" (probable error de tipeo, sin la V) se
--     normalizó a "LV-S048", que es como aparece en el resto del libro.
--   - Dos filas de la última página (aeronave LV-S024) no tenían fecha
--     completa: una sin día ni mes (se descartó, no había forma de
--     reconstruirla) y otra con día 22 sin mes (se asumió noviembre 2025,
--     mismo mes que las entradas anteriores de esa página).
-- ============================================================================

do $$
declare
  v_user_id uuid;
begin
  select id into v_user_id from auth.users where email = 'fileretocambrafrancisco@gmail.com';
  if v_user_id is null then
    raise exception 'No se encontró un usuario con email fileretocambrafrancisco@gmail.com';
  end if;

  -- ---- Aeronaves (solo si no existen ya para este usuario) ----
  select v_user_id, 'LV-CHC', 'C-150', '100HP', 'monomotor', 'terrestre'
  where not exists (select 1 from aeronaves where user_id = v_user_id and matricula = 'LV-CHC');
  select v_user_id, 'LV-JUK', 'C-150', '100HP', 'monomotor', 'terrestre'
  where not exists (select 1 from aeronaves where user_id = v_user_id and matricula = 'LV-JUK');
  select v_user_id, 'LV-S100', 'ECHO', '100HP', 'monomotor', 'terrestre'
  where not exists (select 1 from aeronaves where user_id = v_user_id and matricula = 'LV-S100');
  select v_user_id, 'LV-S048', 'ASTO', '100HP', 'monomotor', 'terrestre'
  where not exists (select 1 from aeronaves where user_id = v_user_id and matricula = 'LV-S048');
  select v_user_id, 'LV-S079', 'ECHO', '100HP', 'monomotor', 'terrestre'
  where not exists (select 1 from aeronaves where user_id = v_user_id and matricula = 'LV-S079');
  select v_user_id, 'LV-HQO', 'SIRA', '100HP', 'monomotor', 'terrestre'
  where not exists (select 1 from aeronaves where user_id = v_user_id and matricula = 'LV-HQO');
  select v_user_id, 'LV-S041', 'PIAT', '80HP', 'monomotor', 'terrestre'
  where not exists (select 1 from aeronaves where user_id = v_user_id and matricula = 'LV-S041');
  select v_user_id, 'LV-CTA', 'C-172', '150HP', 'monomotor', 'terrestre'
  where not exists (select 1 from aeronaves where user_id = v_user_id and matricula = 'LV-CTA');
  select v_user_id, 'LV-S114', 'ECHO', '100HP', 'monomotor', 'terrestre'
  where not exists (select 1 from aeronaves where user_id = v_user_id and matricula = 'LV-S114');
  select v_user_id, 'LV-ASG', 'C-172', null, 'monomotor', 'terrestre'
  where not exists (select 1 from aeronaves where user_id = v_user_id and matricula = 'LV-ASG');
  select v_user_id, 'LV-GQH', 'TWEN', '180HP', 'monomotor', 'terrestre'
  where not exists (select 1 from aeronaves where user_id = v_user_id and matricula = 'LV-GQH');
  select v_user_id, 'LV-S024', 'ASTO', '100HP', 'monomotor', 'terrestre'
  where not exists (select 1 from aeronaves where user_id = v_user_id and matricula = 'LV-S024');

  -- ---- Vuelos ----

end $$;
